import React, { useEffect, useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import AOS from "aos";
import "aos/dist/aos.css";

import img1 from "./assests/dates.jpg";
import img2 from "./assests/nuts.jpg";
import img3 from "./assests/seeds.jpg";

export default function HerbsSpicesHome() {
  const slides = [
    { image: img1, title: "Fresh Dates", offer: "FLAT 10% OFF", coupon: "DATE10" },
    { image: img2, title: "Premium Nuts", offer: "BUY 1 GET 1 FREE", coupon: "NUTS50" },
    { image: img3, title: "Organic Seeds", offer: "20% OFF", coupon: "SEED20" },
  ];

  const [index, setIndex] = useState(0);
  const [menuOpen, setMenuOpen] = useState(false);

  // ---------------- PRODUCT SLIDER ---------------- //
  const products = [
    { img: "/static/images/product1.png", name: "Black Mustard", price: "$286.00" },
    { img: "/static/images/product2.png", name: "Pippali Pepper", price: "$629.00", old: "$700.00", sale: true },
    { img: "/static/images/product3.png", name: "Rosehip Berries", price: "$579.00" },
    { img: "/static/images/product4.png", name: "Red Chilly", price: "$649.00" },
    { img: "/static/images/product5.png", name: "Star Anise", price: "$299.00" },
    { img: "/static/images/product6.png", name: "Cumin Seeds", price: "$150.00" },
    { img: "/static/images/product7.png", name: "Black Pepper", price: "$220.00" },
    { img: "/static/images/product8.png", name: "Dry Ginger", price: "$180.00" },
    { img: "/static/images/product9.png", name: "Cardamom", price: "$750.00" },
    { img: "/static/images/product10.png", name: "Cinnamon Sticks", price: "$480.00" },
  ];

  const [startIndex, setStartIndex] = useState(0);
  const visibleCount = 5;

  const nextProducts = () => {
    setStartIndex((prev) => (prev + visibleCount) % products.length);
  };

  const prevProducts = () => {
    setStartIndex((prev) =>
      prev - visibleCount < 0 ? products.length - visibleCount : prev - visibleCount
    );
  };

  // ---------------- SLIDER AUTO CHANGE ---------------- //
  useEffect(() => {
    AOS.init({ duration: 800 });

    const timer = setInterval(() => {
      setIndex((prev) => (prev + 1) % slides.length);
    }, 4000);

    return () => clearInterval(timer);
  }, []);

  return (
    <div className="position-relative w-100 vh-100 overflow-hidden">

      {/* Background Slider */}
      <div
        className="position-absolute top-0 start-0 w-100 h-100"
        style={{
          backgroundImage: `url(${slides[index].image})`,
          backgroundSize: "cover",
          backgroundPosition: "center",
          transition: "background-image 1s ease-in-out",
        }}
      />

      <div className="position-absolute top-0 start-0 w-100 h-100 bg-dark opacity-50"></div>

      {/* Navbar */}
      <nav className="custom-navbar">
        <div className="nav-brand">✺ Sinthu</div>
        <div className="hamburger" onClick={() => setMenuOpen(!menuOpen)}>☰</div>

        <ul className={`nav-links ${menuOpen ? "open" : ""}`}>
          <li><a href="#">Home</a></li>
          <li><a href="#">Shop</a></li>
          <li><a href="#">Dates</a></li>
          <li><a href="#">Nuts</a></li>
          <li><a href="#">Seeds</a></li>
        </ul>
      </nav>

      {/* SLIDER TEXT */}
      <div
        className="position-relative text-center text-white d-flex flex-column justify-content-center align-items-center h-100 px-3"
        data-aos="fade-up"
        key={index}
      >
        <h1 className="display-1 fw-bold text-shadow">{slides[index].title}</h1>
        <p className="fs-2 fw-semibold mt-3">{slides[index].offer}</p>
        <p className="fs-5 mt-2">
          USE COUPON : <span className="fw-bold text-warning">{slides[index].coupon}</span>
        </p>
      </div>

      {/* LEFT/RIGHT BUTTONS */}
      <button
        onClick={() => setIndex((p) => (p - 1 + slides.length) % slides.length)}
        className="btn btn-dark bg-opacity-75 position-absolute top-50 start-0 translate-middle-y rounded-circle p-3 fs-3"
        style={{ zIndex: 1500 }}
      >
        ❮
      </button>

      <button
        onClick={() => setIndex((p) => (p + 1) % slides.length)}
        className="btn btn-dark bg-opacity-75 position-absolute top-50 end-0 translate-middle-y rounded-circle p-3 fs-3"
        style={{ zIndex: 1500 }}
      >
        ❯
      </button>

      {/* BEST PRODUCTS SECTION */}
      <div className="container py-5 mt-5" data-aos="fade-up">
        <h1 className="text-center mb-5 text-white">Best Products</h1>

        {/* Tabs */}
        <div className="d-flex justify-content-center gap-4 mb-5">
          <button className="product-tab active-tab">Dried seeds</button>
          <button className="product-tab">Spicy Masalas</button>
        </div>

        {/* PRODUCTS LIST — SHOW ONLY 5 AT A TIME */}
        <div className="row justify-content-center g-4">
          {products.slice(startIndex, startIndex + visibleCount).map((p, i) => (
            <div className="col-md-2 col-6" key={i}>
              <div className="product-card position-relative">
                {p.sale && <span className="sale-badge">Sale</span>}
                <img src={p.img} className="product-img" />
                <h5 className="product-title">{p.name}</h5>
                <p className="product-price">
                  {p.price} {p.old && <span className="old-price">{p.old}</span>}
                </p>
              </div>
            </div>
          ))}
        </div>

        {/* SLIDER ARROWS */}
        <div className="d-flex justify-content-center gap-4 mt-4">
          <div className="arrow-btn" onClick={prevProducts}>❮</div>
          <div className="arrow-btn" onClick={nextProducts}>❯</div>
        </div>
      </div>

      {/* CSS */}
      <style>{`
        .product-tab {
          padding: 12px 28px;
          border-radius: 25px;
          border: 2px solid #d08b1c;
          background: white;
          font-size: 18px;
          font-weight: 600;
          color: #a25a06;
          cursor: pointer;
        }
        .active-tab {
          background: #d08b1c;
          color: white;
        }
        .product-card {
          background: white;
          padding: 25px 10px;
          border-radius: 20px;
          text-align: center;
          box-shadow: 0 10px 20px rgba(0, 0, 0, 0.1);
        }
        .product-img {
          width: 100%;
          max-width: 140px;
          height: 140px;
          object-fit: cover;
          border-radius: 50%;
          margin-bottom: 15px;
        }
        .sale-badge {
          position: absolute;
          top: 15px;
          left: 15px;
          background: #d08b1c;
          color: white;
          padding: 4px 10px;
          border-radius: 10px;
          font-size: 14px;
          font-weight: bold;
        }
        .arrow-btn {
          width: 50px;
          height: 50px;
          border-radius: 50%;
          border: 2px solid #d08b1c;
          display: flex;
          justify-content: center;
          align-items: center;
          font-size: 22px;
          cursor: pointer;
        }

        /* Navbar */
        .custom-navbar {
          position: fixed;
          top: 0;
          width: 100%;
          background: rgba(0,0,0,0.75);
          padding: 12px 20px;
          display: flex;
          justify-content: center;
          align-items: center;
          z-index: 3000;
          gap: 40px;
        }
        .nav-brand {
          font-size: 26px;
          font-weight: bold;
          color: gold;
          margin-right: auto;
        }
        .nav-links {
          display: flex;
          justify-content: center;
          align-items: center;
          gap: 35px;
          list-style: none;
        }
        .nav-links li a {
          color: white;
          font-size: 18px;
          text-decoration: none;
        }
        .hamburger {
          font-size: 30px;
          color: white;
          display: none;
        }
